const item = $input.first();
const response = item.json || {};
let tracked = {};
try { tracked = $('Track Revision Attempt').last().json || {}; } catch (error) { tracked = {}; }

let sourcePrompt = '';
try {
  const promptItem = $('Build Alaska Set A Go Prompt').last().json || $('Basic LLM Chain').last().json || {};
  sourcePrompt = promptItem.text || promptItem.output || promptItem.response || promptItem.answer || '';
} catch (error) {
  sourcePrompt = '';
}

const imageGenerationOutput = Array.isArray(response.output)
  ? response.output.find((output) => output.type === 'image_generation_call' && output.result)
  : null;

const rawBase64 =
  imageGenerationOutput?.result ||
  response.data?.[0]?.b64_json ||
  response.data?.[0]?.base64 ||
  response.b64_json ||
  response.image_base64;

if (!rawBase64) {
  throw new Error('No base64 image found. Expected OpenAI response at output[].result or data[0].b64_json.');
}

const base64 = String(rawBase64).replace(/^data:image\/\w+;base64,/, '');
const filename = `alaska_set_a_go_ad_${Date.now()}.png`;

return [
  {
    json: {
      status: 'success',
      filename,
      mimeType: 'image/png',
      binaryProperty: 'data',
      imageBase64: base64,
      prompt: sourcePrompt,
      created: response.created || null,
      usage: response.usage || null,
      revisionAttempt: Number(tracked.revisionAttempt || 0),
      renderAttempt: Number(tracked.renderAttempt || 1),
      scenarioName: tracked.scenarioName || null,
      scenarioCharacterCount: Number(tracked.scenarioCharacterCount || 0)
    },
    binary: {
      data: {
        data: base64,
        mimeType: 'image/png',
        fileName: filename,
        fileExtension: 'png'
      }
    }
  }
];

const item = $input.first();
const response = item.json || {};
const content = response.choices?.[0]?.message?.content || response.output_text || response.text || '';
let parsed;
try {
  parsed = typeof content === 'string' ? JSON.parse(content) : content;
} catch (error) {
  const match = String(content).match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : {};
}
const score = Number(parsed.score ?? 0);
const decision = score >= 9.2 ? 'pass' : score >= 8.0 ? 'revise' : 'fail';
const issuesPrompt = String(parsed.issues_prompt || parsed.issues || 'QA did not return detailed issues. Re-check text, product bottles, promo text, compliance, and overall ad quality.');
let previous = {};
try { previous = $('Convert OpenAI Image to Binary').last(); } catch (error) { previous = {}; }
const imageBase64 = previous.json?.imageBase64 || previous.binary?.data?.data || '';
const filename = previous.json?.filename || `alaska_set_a_go_ad_${Date.now()}.png`;
const binary = previous.binary?.data?.data
  ? previous.binary
  : {
      data: {
        data: imageBase64,
        mimeType: 'image/png',
        fileName: filename,
        fileExtension: 'png'
      }
    };

if (!binary.data?.data) {
  throw new Error('No image binary/base64 available after QA parsing.');
}

return [{
  json: {
    ...previous.json,
    filename,
    qaScore: score,
    qaDecision: decision,
    qaIssuesPrompt: issuesPrompt,
    revisionPrompt: issuesPrompt,
    imageBase64,
    reviewJob: `review_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    renderAttempt: Number(previous.json?.renderAttempt || 1),
    revisionAttempt: Number(previous.json?.revisionAttempt || 0),
    candidateSource: decision === 'pass' ? 'qa-approved output' : decision === 'revise' ? 'qa-revision candidate' : 'discard-regenerate candidate'
  },
  binary
}];

return [{
  json: {
    ...$json,
    failedReason: $json.qaIssuesPrompt,
    discardedAt: new Date().toISOString(),
    nextAction: 'regenerate_from_start'
  }
}];

const input = $input.first();
const binary = input.binary || {};

if (!binary.data?.data) {
  throw new Error('No binary.data image found for Telegram send. Expected previous node to provide binary.data.');
}

const fullCaption = `Alaska SET A GO Review Queue
Review Job: ${$json.reviewJob}
Workflow Attempt: ${$json.renderAttempt || 1}
QA Score: ${Number($json.qaScore).toFixed(2)}
Filename: ${$json.filename}
Candidate Source: ${$json.candidateSource}

QA Notes: ${$json.qaIssuesPrompt}

Click Revise if this image needs changes. After clicking, reply to this photo with the exact revision instructions.`;
const telegramCaption = fullCaption.length > 1024
  ? `${fullCaption.slice(0, 1000)}\n...`
  : fullCaption;

return [{
  json: {
    ...$json,
    telegramChatId: $json.telegramChatId || '-5233739460',
    telegramCaption,
    telegramInlineKeyboard: {
      inline_keyboard: [[
        { text: 'Revise', callback_data: `alaska_revise:${$json.reviewJob}` }
      ]]
    }
  },
  binary
}];

const item = $input.first();
const response = item.json || {};
const content = response.choices?.[0]?.message?.content || response.output_text || response.text || '';
let parsed;
try {
  parsed = typeof content === 'string' ? JSON.parse(content) : content;
} catch (error) {
  const match = String(content).match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : {};
}
let previous = {};
try { previous = $('Parse QA Decision').last(); } catch (error) { previous = {}; }
const approved = Boolean(parsed.approved);
const finalIssuesPrompt = String(parsed.issues_prompt || parsed.issues || 'Final double-check did not return issues.');
const previousIssues = previous.json?.qaIssuesPrompt || '';
return [{
  json: {
    ...previous.json,
    finalDoubleCheckApproved: approved,
    finalDoubleCheckScore: Number(parsed.score ?? previous.json?.qaScore ?? 0),
    finalDoubleCheckIssuesPrompt: finalIssuesPrompt,
    qaIssuesPrompt: approved ? `${previousIssues}\nFinal double-check: ${finalIssuesPrompt}` : finalIssuesPrompt,
    candidateSource: approved ? 'qa-double-check-approved output' : 'double-check-rejected regenerate candidate'
  },
  binary: previous.binary
}];

const item = $input.first();
const current = Number(item.json?.revisionAttempt || 0);
const isRevisionLoop = Boolean(item.json?.revisionPrompt || item.json?.qaDecision === 'revise');
return [{
  json: {
    ...item.json,
    revisionAttempt: isRevisionLoop ? current + 1 : current
  },
  binary: item.binary
}];

const scenarios = [
  {
    name: 'bright wellness tabletop',
    scene: 'a clean bright wellness tabletop with warm yellow light, subtle green wellness accents, soft shadows, and premium supplement-ad styling',
    characterCount: 0
  },
  {
    name: 'healthy morning routine',
    scene: 'a polished Filipino morning routine setting with a breakfast table, water glass, fruits, soft daylight, and a practical daily-wellness mood',
    characterCount: 0
  },
  {
    name: 'pharmacy counter display',
    scene: 'a tidy local pharmacy or supplement counter display with clean shelves, bright lighting, and a trustworthy retail wellness feel',
    characterCount: 0
  },
  {
    name: 'family wellness shelf',
    scene: 'a neat home wellness shelf with supplement bottles, a glass of water, simple healthy-living props, and warm approachable lighting',
    characterCount: 0
  }
];

const selected = scenarios[Math.floor(Math.random() * scenarios.length)];

const promptTemplate = `Create a polished square Facebook ad image for the Alaska SET A GO wellness promotion.

Scenario direction: {{SCENARIO_DIRECTION}}
Character direction: Do not include people, body parts, doctors, lab coats, medical scenes, or patient imagery. The output should feature only the product bottles, tasteful wellness props, background, and ad typography.

The source promotion is SET A GO: BUY 1 TAKE 1 with two Alaska Premium Deep Sea Salmon Fish Oil bottles plus one FREE Alaska Garlic Oil Softgels bottle. Make the output look like a premium, cleaner, sharper, more professional version of the provided set-a-go.jpg reference, not a rough copy.

Product layout: show two large Alaska Premium Deep Sea Salmon Fish Oil bottles as the hero products and one smaller Alaska Garlic Oil Softgels bottle on the right as the free item. Keep all bottles upright, front-facing where possible, crisp, realistic, and not blocked by text. Use fishoil.jpg as the strict reference for the salmon fish oil bottle: Alaska wordmark, yellow label, fish icon, gold/black label bands, EPA/DHA Omega-3 text, 100 Softgels count, softgel capsules, cap seal, and bottle proportions. Use garlicoil.jpg as the strict reference for the garlic oil bottle: Alaska brand, Garlic Oil Softgels wording, garlic artwork, yellow/orange label, 200 Softgels count, softgels, cap seal, and bottle proportions. Do not invent alternate packaging or simplify labels.

Required ad copy: include a bold headline similar to "DOUBLE SUPPORT FOR DAILY WELLNESS". Include a clear red plus sign and "FREE GARLIC OIL" callout near the garlic oil bottle. Include a benefit strip with compliant lifestyle wording similar to "Pair with good habits, not replacement for diet & exercise". Include a strong "BUY 1 TAKE 1" promo badge. Keep all text readable, correctly spelled, modern, and aligned. Do not overcrowd the design.

Compliance and style: avoid medical cure claims, disease treatment/prevention claims, guaranteed results, exaggerated body claims, before/after framing, or scientific/doctor endorsement visuals. Do not include order-now buttons, limited-stock banners, website URLs, QR codes, phone numbers, social handles, clickable-looking UI elements, app buttons, or marketplace buttons. Use a warm yellow wellness palette with enough contrast, realistic commercial lighting, premium product detail, and a clean Facebook ad composition.`;

const prompt = promptTemplate.replace('{{SCENARIO_DIRECTION}}', selected.scene);

return [{
  json: {
    ...$json,
    prompt,
    text: prompt,
    scenarioName: selected.name,
    scenarioCharacterCount: 0,
    revisionAttempt: 0,
    renderAttempt: Number($json.renderAttempt || 0) + 1
  }
}];

const update = $json;
const callback = update.callback_query || update.callbackQuery || null;

if (callback) {
  const data = String(callback.data || '');
  const [rawAction = '', reviewJob = 'unknown'] = data.split(':');
  const action = rawAction.replace(/^alaska_/, '');
  const chat = callback.message?.chat || {};
  return [{
    json: {
      eventType: action === 'revise' ? 'revise_button' : 'unknown_callback',
      telegramAction: action,
      reviewJob,
      callbackData: data,
      callbackQueryId: callback.id || null,
      telegramChatId: String(chat.id || '-5233739460'),
      telegramMessageId: callback.message?.message_id || null,
      callbackResponseText: action === 'revise'
        ? 'Reply to the ad photo with the exact revision instructions.'
        : `Unknown review action: ${data}`,
      promptText: `Please reply directly to the Alaska SET A GO ad photo with the exact revision instructions for review job ${reviewJob}. Example: Make the garlic oil bottle clearer, fix the BUY 1 TAKE 1 badge, and improve the headline spacing.`,
      rawTelegramUpdate: update
    }
  }];
}

const message = update.message || update.edited_message || {};
const chat = message.chat || {};
const text = String(message.text || message.caption || '').trim();
const reply = message.reply_to_message || {};
const photos = Array.isArray(reply.photo) ? reply.photo : [];
const bestPhoto = photos.length ? photos[photos.length - 1] : null;
const caption = String(reply.caption || '');
const jobMatch = caption.match(/Review Job:\s*([^\n]+)/i);

return [{
  json: {
    eventType: text && bestPhoto ? 'revision_text' : 'unsupported_message',
    telegramChatId: String(chat.id || '-5233739460'),
    telegramMessageId: message.message_id || null,
    repliedToMessageId: reply.message_id || null,
    reviewJob: jobMatch?.[1]?.trim() || 'unknown',
    revisionPrompt: text,
    telegramPhotoFileId: bestPhoto?.file_id || null,
    callbackResponseText: text && bestPhoto
      ? 'Revision instructions received. This is ready to be sent into the image edit step.'
      : 'To revise, click Revise under the ad, then reply directly to that ad photo with your revision instructions.',
    rawTelegramUpdate: update
  }
}];

return [{
  json: {
    ...$json,
    nextAction: 'send_to_image_edit',
    note: 'The old Telegram callback query id is intentionally not used here because it expires. Use telegramPhotoFileId to download the replied-to ad image, convert it to base64, then call the OpenAI image edit step with revisionPrompt.'
  }
}];

const item = $input.first();
const json = item.json || {};
const binary = item.binary || {};
const reviewJob = String(json.reviewJob || '').trim();

if (!reviewJob) {
  throw new Error('Cannot store review output because reviewJob is missing.');
}
if (!json.imageBase64) {
  throw new Error('Cannot store review output because imageBase64 is missing.');
}

const store = $getWorkflowStaticData('global');
store.alaskaReviewJobs = store.alaskaReviewJobs || {};
store.alaskaReviewJobOrder = Array.isArray(store.alaskaReviewJobOrder) ? store.alaskaReviewJobOrder : [];

store.alaskaReviewJobs[reviewJob] = {
  reviewJob,
  storedAt: new Date().toISOString(),
  filename: json.filename || null,
  mimeType: json.mimeType || 'image/png',
  imageBase64: json.imageBase64,
  prompt: json.prompt || '',
  qaScore: Number(json.qaScore || 0),
  qaDecision: json.qaDecision || '',
  qaIssuesPrompt: json.qaIssuesPrompt || '',
  revisionAttempt: Number(json.revisionAttempt || 0),
  renderAttempt: Number(json.renderAttempt || 1),
  candidateSource: json.candidateSource || '',
  scenarioName: json.scenarioName || null,
  scenarioCharacterCount: Number(json.scenarioCharacterCount || 0)
};

store.alaskaReviewJobOrder = store.alaskaReviewJobOrder.filter((id) => id !== reviewJob);
store.alaskaReviewJobOrder.push(reviewJob);

const maxStoredJobs = 50;
while (store.alaskaReviewJobOrder.length > maxStoredJobs) {
  const oldJob = store.alaskaReviewJobOrder.shift();
  delete store.alaskaReviewJobs[oldJob];
}

return [{
  json: {
    ...json,
    storedReviewJob: reviewJob,
    storedReviewJobCount: store.alaskaReviewJobOrder.length
  },
  binary
}];

const item = $input.first();
const json = item.json || {};
const reviewJob = String(json.reviewJob || '').trim();
const userRevisionPrompt = String(json.revisionPrompt || '').trim();

if (!reviewJob || reviewJob === 'unknown') {
  throw new Error('Cannot load stored review output because reviewJob is missing. Reply directly to a review photo whose caption contains Review Job.');
}
if (!userRevisionPrompt) {
  throw new Error('Cannot revise because revisionPrompt is empty.');
}

const store = $getWorkflowStaticData('global');
const record = store.alaskaReviewJobs?.[reviewJob];
if (!record) {
  throw new Error(`No stored image found for reviewJob ${reviewJob}. It may be older than the retained local store window. Generate a fresh review image and reply to that photo.`);
}

const revisionPrompt = `Revise the stored Alaska SET A GO Facebook ad image according to this human feedback: "${userRevisionPrompt}". Preserve the same square ad layout, two Alaska Premium Deep Sea Salmon Fish Oil bottles, one free Alaska Garlic Oil Softgels bottle, product packaging accuracy, warm yellow wellness palette, readable headline, + FREE GARLIC OIL callout, benefit strip, BUY 1 TAKE 1 badge, lighting, and scene unless the feedback explicitly asks to change them. Keep the ad free of medical cure claims, disease claims, order-now buttons, limited-stock banners, website URLs, QR codes, phone numbers, social handles, clickable-looking UI elements, app buttons, or marketplace buttons. Reference source of truth: set-a-go.jpg defines the promotion and composition; fishoil.jpg and garlicoil.jpg define the real bottle and label details. Do not remove or redesign legitimate packaging elements from the references; only change packaging if the instruction is to restore it closer to the references.`;

return [{
  json: {
    ...record,
    ...json,
    imageBase64: record.imageBase64,
    filename: record.filename || json.filename || `alaska_set_a_go_revision_${Date.now()}.png`,
    mimeType: record.mimeType || 'image/png',
    prompt: record.prompt || '',
    originalQaScore: record.qaScore,
    originalQaIssuesPrompt: record.qaIssuesPrompt,
    humanRevisionPrompt: userRevisionPrompt,
    revisionPrompt,
    revisionAttempt: Number(record.revisionAttempt || 0),
    renderAttempt: Number(record.renderAttempt || 1),
    candidateSource: 'human-requested revision candidate',
    loadedStoredReviewJob: reviewJob
  },
  binary: {
    data: {
      data: record.imageBase64,
      mimeType: record.mimeType || 'image/png',
      fileName: record.filename || `alaska_set_a_go_revision_source_${reviewJob}.png`,
      fileExtension: 'png'
    }
  }
}];
